import pandas as pd
from unittest.mock import patch

def test_object_bool_any_dispatches_to_max():
    df = pd.DataFrame({"g": [1, 1, 2, 2], "v": pd.Series([True, False, True, False], dtype=object)})
    seen = []
    from pandas.core.groupby.ops import BaseGrouper
    orig = BaseGrouper._cython_operation
    def wrapper(self, *args, **kwargs):
        for a in list(args) + list(kwargs.values()):
            if isinstance(a, str) and a in ("any", "all", "max", "min"):
                seen.append(a)
        return orig(self, *args, **kwargs)
    with patch.object(BaseGrouper, "_cython_operation", wrapper):
        df.groupby("g")["v"].any()
    assert "max" in seen, f"object-dtype any() did not dispatch to max, saw {seen}"

